const cfg=window.AFRIRISE_CONFIG;async function check(){const box=document.querySelector('#donation-status'),token=sessionStorage.getItem('afririse-status-token');if(!cfg.apiBase||!token){document.querySelector('#status-heading').textContent='No verified confirmation yet.';box.textContent='A secure confirmation token from your checkout session is required. Returning from a payment page alone does not confirm a donation.';return}try{const r=await fetch(cfg.apiBase+'/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token})});const result=await r.json();if(!r.ok)throw new Error(result.error);box.replaceChildren();const add=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;box.append(n)};if(result.receipt){document.querySelector('#status-heading').textContent='Thank you for being part of the rise.';add('h2','Donation acknowledged');add('p',new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(result.receipt.amount_cents/100));add('p','Reference: '+result.receipt.receipt_number);add('p','Issued: '+new Date(result.receipt.issued_at).toLocaleString());document.querySelector('#print-receipt').hidden=false}else{document.querySelector('#status-heading').textContent='Your payment is awaiting confirmation.';add('p','We have not yet recorded a verified successful payment. Please check again shortly.')} }catch(e){box.textContent=e.message}}document.querySelector('#retry-status').addEventListener('click',check);document.querySelector('#print-receipt').addEventListener('click',()=>window.print());check();
